{"tool": "write", "path": "tests/test_export_extra.py", "content": "import unittest

from reports import export_csv


class ExportCsvExtraTests(unittest.TestCase):
    def test_generators_and_empty_columns(self):
        rows = ({"a": i} for i in range(2))
        cols = (name for name in ["a", "b"])
        self.assertEqual(export_csv(rows, cols), "a,b\r\n0,\r\n1,\r\n")

    def test_newlines_quotes_unicode_and_none(self):
        rows = [{"x": "a\r\nb", "y": None, "z": "é,"}]
        expected = "x,y,z\r\n" + '"a\r\nb"' + ",," + '"é,"' + "\r\n"
        self.assertEqual(export_csv(rows, ["x", "y", "z"]), expected)

    def test_duplicate_or_non_string_columns_raise(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])
        with self.assertRaises(ValueError):
            export_csv([], [1])

    def test_ignores_unselected_and_does_not_mutate(self):
        row = {"a": 1, "b": 2}
        cols = ["b"]
        self.assertEqual(export_csv([row], cols), "b\r\n2\r\n")
        self.assertEqual(row, {"a": 1, "b": 2})
        self.assertEqual(cols, ["b"])


if __name__ == "__main__":
    unittest.main()
